import { sendRequest } from '@weavix/sdk-core';
import type { ApiCallPayload, ApiCallResult } from './types';

export interface TrackerApiCallOptions {
    pathParams?: Record<string, string>;
    queryParams?: Record<string, unknown>;
    bodyParams?: Record<string, unknown>;
    file?: File;
}

function buildPayload(
    method: string,
    url: string,
    options: TrackerApiCallOptions = {},
    version: string,
): ApiCallPayload {
    return {
        version,
        method,
        url,
        pathParams: options.pathParams ?? {},
        queryParams: options.queryParams ?? {},
        bodyParams: options.bodyParams ?? {},
        file: options.file,
    };
}

export interface TrackerApiInitOptions {
    apiVersion?: string;
}

/**
 * Untyped runtime API класс. v3-методы возвращают Proxy, который при обращении
 * по любому ключу строит call. Типизация добавляется в публикуемых пакетах
 * через cast (см. typed wrapper).
 */
export class TrackerApi {
    private static readonly V3_VERSION = 'v3';

    get v3(): {
        get: Record<string, (opts: TrackerApiCallOptions) => Promise<unknown>>;
        post: Record<string, (opts: TrackerApiCallOptions) => Promise<unknown>>;
        put: Record<string, (opts: TrackerApiCallOptions) => Promise<unknown>>;
        patch: Record<string, (opts: TrackerApiCallOptions) => Promise<unknown>>;
        delete: Record<string, (opts: TrackerApiCallOptions) => Promise<unknown>>;
    } {
        return {
            get: this.createMethodProxy('GET'),
            post: this.createMethodProxy('POST'),
            put: this.createMethodProxy('PUT'),
            patch: this.createMethodProxy('PATCH'),
            delete: this.createMethodProxy('DELETE'),
        };
    }

    private createMethodProxy(
        method: string,
    ): Record<string, (opts: TrackerApiCallOptions) => Promise<unknown>> {
        const self = this;
        return new Proxy({} as Record<string, (opts: TrackerApiCallOptions) => Promise<unknown>>, {
            get(_, path: string) {
                return (payload: TrackerApiCallOptions) =>
                    self.call(method, path, payload, TrackerApi.V3_VERSION);
            },
        });
    }

    private call(
        method: string,
        url: string,
        options: TrackerApiCallOptions = {},
        requestVersion: string,
    ): Promise<ApiCallResult> {
        const payload: ApiCallPayload = buildPayload(method, url, options, requestVersion);
        return sendRequest('api.tracker.call', payload) as Promise<ApiCallResult>;
    }
}

export const trackerApi = new TrackerApi();
