import {
    type LocalizedString as StructuralLocalizedString,
    getLocalizedString as baseGetLocalizedString,
} from '@weavix/sdk-core';
import type { LocalizedString } from '../types/primitives';

/**
 * Получить локализованную строку на основе языка.
 * Принимает `LocalizedString` из @weavix/tracker-core.
 */
export function getLocalizedString(
    value: LocalizedString,
    language: string | undefined,
    fallbackLanguage = 'ru',
): string {
    return baseGetLocalizedString(value as StructuralLocalizedString, language, fallbackLanguage);
}
